function ArrowDownIcon(){return <svg width="16" height="32" viewBox="0 0 16 32" fill="none" aria-hidden="true"><path d="M8 0v29m-4-4 4 4 4-4" stroke="currentColor" strokeWidth="1.2"/></svg>}
function seekOriginal(entry:Entry,seconds:number){const audio=document.getElementById(`recording-${entry.id}`) as HTMLAudioElement|null;if(audio){audio.currentTime=seconds;void audio.play().catch(()=>undefined)}}
function Anchor({entry,index}:{entry:Entry;index:number}){const a=entry.anchors?.[index];if(!a||a.kind==='none')return null;if(a.kind==='message')return <small className="anchor-chip">AI material · message {a.index+1}</small>;if(a.kind==='page')return <small className="anchor-chip">p.{a.page}</small>;return a.kind==='time'?<button className="anchor-chip" onClick={()=>seekOriginal(entry,a.seconds)}><Play size={11}/>{clock(a.seconds)}</button>:<a className="anchor-chip" href={a.url} target="_blank" rel="noreferrer noopener"><LinkIcon size={11}/>{tr('Open source')}</a>}
function OriginalText({entry,highlight,concepts=[],openConcept,ask}:{entry:Entry;highlight:number[];concepts?:Concept[];openConcept?:(id:string)=>void;ask?:(i:number)=>void}){
 let cursor=0;const parts:React.ReactNode[]=[];
 entry.sentences.forEach((sentence,i)=>{
  const start=entry.body.indexOf(sentence,cursor);if(start<0)return;
  parts.push(entry.body.slice(cursor,start));const anchor=entry.anchors?.[i];
  const inner=concepts.length&&anchor?.kind!=='time'?<ConceptText text={sentence} concepts={concepts} open={openConcept}/>:sentence;
  const text=highlight.includes(i)?<mark id={`sentence-${i}`}>{inner}</mark>:inner;
  parts.push(anchor?.kind==='time'?<button type="button" key={i} className="timed" title={tr('Play at {time}',{time:clock(anchor.seconds)})} onClick={()=>seekOriginal(entry,anchor.seconds)}>{text}</button>:<span key={i} className="sentence">{text}{ask&&<button type="button" className="ask-sentence" title={tr('Open as a question')} aria-label={tr('Open as a question')} onClick={()=>ask(i)}><CircleHelp size={13}/></button>}</span>);
  cursor=start+sentence.length;
 });
 parts.push(entry.body.slice(cursor));
 return <>{entry.anchors?.some(a=>a.kind==='time')&&<audio id={`recording-${entry.id}`} controls preload="metadata" style={{display:'block',width:'100%',marginBottom:20}} src={`${import.meta.env.BASE_URL}api/personal/material-audio/${entry.id}`} onLoadedMetadata={e=>{const anchor=entry.anchors?.[highlight[0]];if(anchor?.kind==='time')e.currentTarget.currentTime=anchor.seconds}}/>}{entry.meta?.source?.includes(tr('AI material'))&&<span className="eyebrow">{tr('AI MATERIAL · NOT YOUR ORIGINAL WORDS')}</span>}{parts}</>;
}
/** The note's title: MOONS may suggest one when structuring; the user can edit it or switch back at any time. */
function EntryTitle({entry,save}:{entry:Entry;save:(title:string|undefined,source:'user'|'ai'|undefined)=>void}){
  const [editing,setEditing]=useState(false),[draft,setDraft]=useState('');
  const suggested=entry.analysis?.suggestedTitle,fromAi=entry.meta?.titleSource==='ai';
  const done=(t:string|undefined,src:'user'|'ai'|undefined)=>{save(t,src);setEditing(false)};
  if(!editing)return <div className="title-line"><h1>{label(entry)}</h1>{fromAi&&<span className="title-badge" title={tr('MOONS suggested this title when structuring. Your original is unchanged.')}>{tr('Suggested')}</span>}<button className="icon-button" aria-label={tr('Edit title')} onClick={()=>{setDraft(entry.title??'');setEditing(true)}}><PenLine size={15}/></button></div>;
  return <form className="title-edit" onSubmit={e=>{e.preventDefault();const t=draft.trim();done(t||undefined,t?'user':undefined)}}>
    <input autoFocus aria-label={tr('Title')} maxLength={120} value={draft} placeholder={label({...entry,title:undefined})} onChange={e=>setDraft(e.target.value)} onKeyDown={e=>{if(e.key==='Escape')setEditing(false)}}/>
    <div className="title-edit-actions"><button className="primary small">{tr('Save')}</button>{suggested&&suggested!==entry.title&&<button type="button" className="text-button" onClick={()=>done(suggested,'ai')}>{tr('Use MOONS’s suggestion: {title}',{title:suggested})}</button>}<button type="button" className="text-button" onClick={()=>setEditing(false)}>{tr('Cancel')}</button></div>
  </form>;
}

function EntryCard({entry,store,open,analyze,tag,busy}:{entry:Entry;store:Store;open:()=>void;analyze:()=>void;tag:()=>void;busy:boolean}){const Icon=(entry.mediaType&&kindIcons[entry.mediaType])||(entry.kind==='media'?FileText:Flame);return <article className="entry-card" draggable onDragStart={e=>{e.dataTransfer.setData('application/x-moons-entry',entry.id);e.dataTransfer.setData('text/plain',entry.id)}}><div className="card-meta"><span><Icon size={14}/>{entry.kind==='dump'?'spark':'material'}{entry.example&&<small className="example-label">Sample</small>}{entry.comparison&&<small className="example-label">{tr('Compared')}</small>}</span><span>{date(entry.createdAt)}</span></div><button className="card-content" onClick={open}><h3>{entry.title??entry.body.slice(0,30)+(entry.body.length>30?'…':'')}</h3><p>{entry.body}</p></button><div className="card-tags">{entry.planetIds.map(id=>{const p=store.planets.find(p=>p.id===id);return p?<button key={id} onClick={tag}><i style={{background:p.color}}/>{p.name}</button>:null})}{!entry.planetIds.length&&<button onClick={tag}><Plus size={12}/>{tr('Dwarf Planet')}</button>}</div><div className="card-bottom"><span className={`status status-${busy?'analyzing':entry.status}`}><i/>{busy?statuses.analyzing:statuses[entry.status]}</span><button onClick={analyze} className="text-button" disabled={busy} aria-label={`${label(entry)} ${entry.analysis?tr('View structure'):tr('Structure this')}`}>{busy?<LoaderCircle className="spin" size={14}/>:<>{entry.analysis?tr('View structure'):tr('Structure this')} <ArrowUpRight size={13}/></>}</button></div></article>}

function TagModal({entry,store,close,save,create}:{entry:Entry;store:Store;close:()=>void;save:(ids:string[])=>void;create:()=>void}){const [ids,setIds]=useState(entry.planetIds);return <Modal title={tr('Classify note')} close={close}><p>{tr('Choose 모행성. Leave empty for Dwarf Planet.')}</p><div className="planet-options">{store.planets.map(p=><button className={ids.includes(p.id)?'selected':''} key={p.id} onClick={()=>setIds(ids.includes(p.id)?ids.filter(id=>id!==p.id):[...ids,p.id])} aria-pressed={ids.includes(p.id)}><i style={{background:p.color}}/>{p.name}<span>{ids.includes(p.id)?<Check size={16}/>:<Plus size={16}/>}</span></button>)}</div><button className="text-button" onClick={create}><Plus size={15}/>{tr('Create 모행성')}</button><div className="modal-actions"><span className="muted">{ids.length} selected</span><button className="primary" onClick={()=>save(ids)}>{tr('Save')} <Check size={16}/></button></div></Modal>}
function PlanetModal({names,close,save}:{names:string[];close:()=>void;save:(name:string,color:string)=>void}){const [name,setName]=useState(''),[color,setColor]=useState('#adc5ef');const colors=['#adc5ef','#d3c6ec','#c9dccb','#e9c7b4','#eddcaa'];const duplicate=names.includes(name.trim());return <Modal title={tr('Create 모행성')} close={close}><form onSubmit={e=>{e.preventDefault();if(name.trim()&&!duplicate)save(name.trim(),color)}}><label className="form-label">{tr('Topic name')}<input autoComplete="off" maxLength={20} required placeholder={tr('e.g. Design, Books, Daily life')} value={name} onChange={e=>setName(e.target.value)}/></label>{duplicate&&<p className="field-error">{tr('A planet with this name already exists.')}</p>}<span className="label">{tr('Color')}</span><div className="color-options">{colors.map(c=><button key={c} type="button" aria-label={`${c} color`} aria-pressed={c===color} style={{background:c}} onClick={()=>setColor(c)}>{color===c&&<Check size={20}/>}</button>)}</div><div className="modal-actions"><button className="secondary" type="button" onClick={close}>{tr('Cancel')}</button><button className="primary" disabled={!name.trim()||duplicate}>{tr('Create 모행성')} <Plus size={16}/></button></div></form></Modal>}

function CheckRow({onCheck,existing,readonly}:{onCheck:(v:'agree'|'mean',comment?:string)=>Promise<boolean>;existing?:{verdict:string;comment?:string};readonly:boolean}){
  const [mean,setMean]=useState(false),[comment,setComment]=useState(''),[busy,setBusy]=useState(false);
  async function send(v:'agree'|'mean'){setBusy(true);const ok=await onCheck(v,v==='mean'?comment.trim():undefined);setBusy(false);if(ok)setMean(false)}
  return <div className="check-row">
    <div><button className={existing?.verdict==='agree'?'selected':''} disabled={readonly||busy} onClick={()=>void send('agree')}>{tr('That’s it')}</button><button className={existing?.verdict==='mean'||mean?'selected':''} disabled={readonly||busy} onClick={()=>setMean(!mean)}>{tr('I mean…')}</button></div>
    {existing?.comment&&!mean&&<small>“{existing.comment}”</small>}
    {mean&&<div className="mean-box"><textarea aria-label={tr('What did you mean?')} maxLength={200} placeholder={tr('What did you mean? It’s fine to leave it rough.')} value={comment} onChange={e=>setComment(e.target.value)}/><button className="primary small" disabled={busy} onClick={()=>void send('mean')}>{busy?<LoaderCircle className="spin" size={13}/>:null}Save</button></div>}
  </div>;
}
function NodePanel({claims,concepts,renaming,setRenaming,rename,node,entry,analysis,readonly,close,source,update,dismiss,check,ask,toPlanner}:{claims?:React.ReactNode;concepts?:React.ReactNode;renaming?:boolean;setRenaming?:(on:boolean)=>void;rename?:(text:string)=>void;node:GNode;entry:Entry;analysis:NonNullable<Entry['analysis']>;readonly:boolean;close:()=>void;toPlanner?:(title:string)=>void;source:(i:number[])=>void;update:(text:string)=>boolean;dismiss:(id:string)=>void;check:(t:'node'|'emotion',id:string,v:'agree'|'mean',comment?:string)=>Promise<boolean>;ask:()=>void}){
  const [text,setText]=useState('');const found=(t:string,id:string)=>entry.checks?.find(c=>c.targetType===t&&c.targetId===id);
  return <aside className="node-panel"><header><span className="eyebrow">{tr('KEEP EXPLORING')}</span><button className="icon-button" onClick={close} aria-label={tr('Close node details')}><X size={18}/></button></header><h2>{node.role}</h2><blockquote>{node.empty?tr('Add what you have learned.'):renaming&&rename?<RenameInput value={nodeText(node)} save={t=>{rename(t);setRenaming?.(false)}} cancel={()=>setRenaming?.(false)}/>:nodeText(node)}{node.edited&&!renaming&&<small className="node-original">{tr('Original: {text}',{text:node.text})}</small>}</blockquote>{rename&&!node.empty&&!renaming&&<button className="text-button rename-button" onClick={()=>setRenaming?.(true)}><PenLine size={14}/>{tr('Fix the wording')}</button>}{node.source.length>0&&<button className="text-button" onClick={()=>source(node.source)}><LinkIcon size={14}/>{tr('View source')}</button>}
  {concepts}{claims}{!node.empty&&<div className="panel-block"><h3>{tr('Is this what you meant?')}</h3><CheckRow readonly={readonly} existing={found('node',node.id)} onCheck={(v,c)=>check('node',node.id,v,c)}/></div>}
  {(node.emotions?.length??0)>0&&<div className="panel-block"><h3>{tr('Emotions MOONS heard')}</h3>{node.emotions!.map(em=><div key={em.id} className="emotion-detail"><span className={`emotion f-${em.family}`}>{em.word}<i>{'●'.repeat(em.intensity)}</i></span><small>{em.family} · “{em.evidence}”</small><CheckRow readonly={readonly} existing={found('emotion',em.id)} onCheck={(v,c)=>check('emotion',em.id,v,c)}/></div>)}</div>}
  {analysis.signals.filter(s=>s.nodeId===node.id).map(s=><div key={s.id} className={`signal-detail ${s.kind} ${s.state!=='open'?'inactive':''}`}><strong>{s.kind==='gap'?tr('To look up (your mark)'):s.kind==='study'?tr('Explore further'):tr('Check this idea')}</strong><p>{s.reason}</p>{s.kind==='gap'&&s.state==='open'&&toPlanner&&!readonly&&<button className="text-button" onClick={()=>toPlanner(tr('Look up and fill in: {text}',{text:node.text.slice(0,60)}))}>{tr('Add to today’s planner')}</button>}{s.state==='open'?<button className="text-button" disabled={readonly} onClick={()=>dismiss(s.id)}>{tr('Dismiss signal')} <Check size={14}/></button>:<span><Check size={13}/> {s.state==='dismissed'?'Dismissed':'Resolved'}</span>}</div>)}
  {node.updates.length>0&&<div className="update-list"><h3>{tr('Updates')}</h3>{node.updates.map(u=><div key={u.id}><time>{date(u.createdAt)}</time><p>{u.text}</p>{u.recheck&&<small>{u.recheck.resolved?'Resolved':tr('Still open')} · {u.recheck.reason}</small>}</div>)}</div>}
  {!readonly&&<form onSubmit={e=>{e.preventDefault();if(update(text))setText('')}}><label htmlFor="update-text">{tr('Add an update')}</label><textarea id="update-text" placeholder={tr('What did you learn?')} value={text} onChange={e=>setText(e.target.value)} maxLength={10000}/><button className="primary" disabled={!text.trim()}>{tr('Add update')} <Plus size={16}/></button><small>{tr('Your original is preserved.')}</small></form>}
  <button className="secondary ask-moons" onClick={ask}><MessageCircle size={15}/>{tr('Ask MOONS about this')}</button></aside>}
